{
	// Handle invalid clock ID as per POSIX
	if (clock_id == CLOCK_INVALID) {
		errno = EINVAL;
		return -1;
	}

	// If res is NULL, POSIX states the function should succeed without storing
	// the resolution. The original Zephyr implementation crashes here.
	// This mock prevents the crash and adheres to POSIX behavior.
	if (res == NULL) {
